#include "stdafx.h"#include "ServerThreadBase.h"#include <EventString.h>#include "MessageList.h"#include <EventEntry.h>#include "LogFile.h"#include "LogFile.h"int SortMessage(const void * d1, const void * d2 );SMessage* Mess(SSendToModel& send){  static CMessageList thisMess;  SMessage fnd;  fnd.eData = send.eData;  StrCPY( fnd.szName, send.szValue, sizeof(fnd.szName) );  return (SMessage*)bsearch( &fnd, thisMess.m_list, thisMess.m_nCount, sizeof(SMessage), SortMessage );}BOOL KServerThreadBase::PutModelLocal( LPCTSTR szUser, SSendToModel& send ){	//VM: 17.07.2024	SSendToModel localsend;	localsend = send;	// ...	CLogFile::Log ("KServerThreadBase::PutModelLocal_1: send.szValue %S", send.szValue);  OutputDebugString( "попытка установить значение для \"");  OutputDebugString( send.szName );  OutputDebugString( "\" в \"" );  OutputDebugString( send.szValue );  OutputDebugString( "\"\n" );  CEventString str;  bool bMessage = send.bMessage;  DWORD dwMess = CEventLogType::etUnknown;  BOOL bExtPutter = FALSE;  // Простое текстовое сообщение  if (( send.eData == id_Msg )||( send.eData == id_Custom ))  {    str.Event(send.szName);    dwMess = (DWORD)send.eType;    bExtPutter = TRUE;  }  else  {    for( int i=0; i<_countof(g_extensionsCont); i++ )    {      if( !g_extensionsCont[i].pPutModelRSUCall )        continue;      DWORD r = g_extensionsCont[i].pPutModelRSUCall( szUser, send, str );      if( r != CEventLogType::etUnknown && r != CEventLogType::etError )      {        if( !str.IsEmpty() )          OutputDebugString( str.GetBuffer() ), OutputDebugString("\n");        dwMess = r;        bExtPutter = TRUE;        break;      }    }  }  if( !bExtPutter )  {    CBase* pBase = FindConnPointLocal( send.szName, send.eData );    if ( pBase == NULL )       return FALSE;    //    SMessage* mess = Mess(send);    //    dwMess = CEventLogType::etError;    if ( mess != NULL )    {      if ( mess->PutMdl( send, pBase, str ) )        dwMess = mess->def->dwLog;    }    else if ( send.bMessage )    {      static char* szFiltr = "Не найдено сообщение '%s'.'%s'";      str.Event( szFiltr, send.szName, send.szValue );    }  }  if ( bMessage && !str.IsEmpty() && dwMess!=CEventLogType::etSameValue )  {    CEventEntry entry;    SSendToModel* Send = static_cast<SSendToModel*>(&entry);	//VM: 17.07.2024    //memcpy( Send, &send, sizeof(send) );	memcpy( Send, &localsend, sizeof(send) );    //    entry.nMess = dwMess;    lstrcpyn( entry.szUser, szUser, sizeof(entry.szUser) );    lstrcpyn( entry.szText, str.GetBuffer(), sizeof(entry.szText) );	CLogFile::Log ("KServerThreadBase::PutModelLocal: entry.szUser %s, entry.szText %s", entry.szUser, entry.szText);    //    char* p = strchr( entry.szUser, '@' );    if ( p ) *p = 0;    //	CLogFile::Log ("KServerThreadBase::PutModelLocal_2: nMess %d, eType %d, eData %d, szText %s",	entry.nMess, entry.eType, entry.eData, entry.szText);    WriteEvents( entry );	return TRUE;  }  return FALSE;}